package got.client.ambient;
import got.GOTMod; import net.minecraft.client.model.geom.ModelLayerLocation; import net.minecraft.client.renderer.entity.*; import net.minecraft.resources.ResourceLocation; import net.minecraft.world.entity.Mob; import java.util.function.Function;
public final class GOTAmbientRenderer<T extends Mob> extends MobRenderer<T,GOTAmbientModel<T>> { private final float scale; private final Function<T,String> tex; public GOTAmbientRenderer(EntityRendererProvider.Context c,ModelLayerLocation l,GOTAmbientModel.Kind k,float shadow,float scale,Function<T,String> tex){super(c,new GOTAmbientModel<>(c.bakeLayer(l),k),shadow);this.scale=scale;this.tex=tex;} public GOTAmbientRenderer(EntityRendererProvider.Context c,ModelLayerLocation l,GOTAmbientModel.Kind k,float shadow,Function<T,String> tex){this(c,l,k,shadow,1,tex);} public ResourceLocation getTextureLocation(T e){return new ResourceLocation(GOTMod.MOD_ID,tex.apply(e));} protected void scale(T e,com.mojang.blaze3d.vertex.PoseStack p,float f){p.scale(scale,scale,scale);} }
